def merge(arr, left, mid, right):
    tmp = []
    i, j = left, mid + 1

    while i <= mid and j <= right:
        if arr[i] <= arr[j]:
            tmp.append(arr[i])
            i += 1
        else:
            tmp.append(arr[j])
            j += 1
    while i <= mid:
        tmp.append(arr[i])
        i += 1
    while j <= right:
        tmp.append(arr[j])
        j += 1

    for l in range(len(tmp)):
        arr[left + l] = tmp[l]

def merge_sort(arr, left, right):
    if left >= right:
        return
    mid = (left + right) // 2
    merge_sort(arr, left, mid)
    merge_sort(arr, mid + 1, right)
    merge(arr, left, mid, right)

arr = [5, 3, 8, 1, 2]
merge_sort(arr, 0, len(arr) - 1)
print(*arr)  # 1 2 3 5 8
